	Message       string            `json:"message,omitempty"`
	Status        string            `json:"status,omitempty"`
	Messages      []json.RawMessage `json:"messages,omitempty"`
	ModifiedFiles []string          `json:"modified_files,omitempty"`
}

func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	if len(input) == 0 {
		return nil, nil
	}

	var payload ampHookPayload
	if err := json.Unmarshal(input, &payload); err != nil {
		return nil, fmt.Errorf("parse hook payload: %w", err)
	}

	sessionID := payload.ThreadID
	if sessionID == "" {
		return nil, nil
	}

	now := time.Now().UTC().Format(time.RFC3339)
	sessionRef := transcriptPath(sessionID)
	model := a.modelFromExportedThread(sessionID, sessionRef)

	switch hookName {
	case "session.start":
		return &protocol.EventJSON{
			Type:       1,
			SessionID:  sessionID,
			SessionRef: sessionRef,
			Model:      model,
			Timestamp:  now,
		}, nil

	case "agent.start":
		if err := appendBootstrapTranscriptEntry(sessionRef, ampTranscriptEntry{
			Type:     "agent.start",
			ThreadID: sessionID,
			Message:  payload.Message,
		}); err != nil {
			return nil, err
		}
		return &protocol.EventJSON{
			Type:       2,
			SessionID:  sessionID,
			SessionRef: sessionRef,
			Prompt:     payload.Message,
			Model:      model,
			Timestamp:  now,
		}, nil

	case "agent.end":
		if err := appendBootstrapTranscriptEntry(sessionRef, ampTranscriptEntry{
			Type:     "agent.end",
			ThreadID: sessionID,
			Message:  payload.Message,
		}); err != nil {
			return nil, err
		}
		return &protocol.EventJSON{
			Type:       3,
			SessionID:  sessionID,
			SessionRef: sessionRef,
			Model:      model,
			Timestamp:  now,
		}, nil

	default:
		return nil, nil
	}
}

func appendBootstrapTranscriptEntry(path string, entry ampTranscriptEntry) error {
	if data, err := os.ReadFile(path); err == nil && len(bytes.TrimSpace(data)) > 0 {
		if _, err := parseAmpThread(data); err == nil {
			return nil
		}
	}
	return appendTranscriptEntry(path, entry)
}

func (a *Agent) modelFromExportedThread(threadID string, sessionRef string) string {
	if strings.TrimSpace(threadID) == "" || strings.TrimSpace(sessionRef) == "" {
		return ""
	}
	runner := a.CommandRunner
	if runner == nil {
		runner = &DefaultCommandRunner{}
	}
	if data, err := os.ReadFile(sessionRef); err == nil && len(bytes.TrimSpace(data)) > 0 {
		if thread, err := parseAmpThread(data); err == nil {
			return latestThreadModel(thread)
		}
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return ""
	}
	ctx, cancel := context.WithTimeout(context.Background(), prepareTranscriptTimeout)
	defer cancel()
	if _, err := runner.ExportThread(ctx, threadID, sessionRef); err != nil {
		return ""
	}
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return ""
	}
	thread, err := parseAmpThread(data)
	if err != nil {
		return ""
	}
	return latestThreadModel(thread)
}

