package amp

import (
	"os"
	"testing"
)

func TestAmpEnvStripsBunVars(t *testing.T) {
	t.Setenv("BUN_BE_BUN", "1")
	t.Setenv("BUN_INSPECT", "0.0.0.0:9229")
	t.Setenv("BUN_DEBUG_QUIET_LOGS", "1")
	t.Setenv("KEEP_ME", "yes")
	env := ampEnv()
	for _, kv := range env {
		if len(kv) >= 4 && kv[:4] == "BUN_" {
			t.Fatalf("env still contains Bun var: %q", kv)
		}
	}
	found := false
	for _, kv := range env {
		if kv == "KEEP_ME=yes" {
			found = true
			break
		}
	}
	if !found {
		t.Fatal("expected non-Bun env vars to be preserved")
	}
	// sanity: explicitly check the actual process env hasn't been mutated
	if os.Getenv("KEEP_ME") != "yes" {
		t.Fatal("test setup error")
	}
}

func TestIsBunEnvVar(t *testing.T) {
	cases := map[string]bool{
		"BUN_BE_BUN":           true,
		"BUN_INSPECT":          true,
		"BUN_DEBUG_FOO":        true,
		"BUN_INSTALL":          false,
		"BUN_INSTALL_CACHE":    false,
		"PATH":                 false,
		"PLUGINS":              false,
		"BUN_INTERNAL_IPC_FD":  true,
	}
	for key, want := range cases {
		if got := isBunEnvVar(key); got != want {
			t.Errorf("isBunEnvVar(%q) = %v, want %v", key, got, want)
		}
	}
}

